$('#confirmCard').onclick=()=>{const playerId=$('#cardPlayer').value,player=state.players.find(p=>p.id===playerId),manual=$('#cardPlayerManual').value.trim();let type=pendingCardType;const priorYellow=playerId&&state.events.some(e=>e.playerId===playerId&&e.id==='yellowCard');if(type==='yellowCard'&&priorYellow){if(!confirm('Este jogador já tem amarelo. Registar como segundo amarelo e expulsão?'))return;type='secondYellow'}const playerLabel=player?`${player.number?'#'+player.number+' ':''}${player.name||player.position||'Jogador'}`:manual||'Jogador não identificado';const reason=$('#cardReason').value,detail=$('#cardNote').value.trim();if(player&&type==='yellowCard'){player.tags=player.tags||[];if(!player.tags.includes('Risco disciplinar'))player.tags.push('Risco disciplinar')}recordEvent(type,{playerId:playerId||null,player:playerLabel,cardTeam:$('#cardTeam').value,reason,note:[reason,detail].filter(Boolean).join(' — ')});$('#cardDialog').close();pendingCardType=null};
