$('#resetBtn').onclick=()=>{if(confirm('Começar uma nova observação? Guarde primeiro o relatório atual se pretender consultá-lo mais tarde.')){clearInterval(timer);activeReportId=null;state=blank();sync();save()}};
document.addEventListener('input',e=>{if(e.target.id==='team')state.team=e.target.value;if([...observationFields,...quickFields,...conclusionFields].includes(e.target.id))state[e.target.id]=e.target.value;if(quickFields.includes(e.target.id))renderQuickContext();if(['blockHeight','pressingStyle','buildUpStyle','attackTempo'].includes(e.target.id))state[e.target.id]=e.target.value;if(e.target.dataset.note!==undefined)state.notes[e.target.dataset.note]=e.target.value;if(e.target.id==='vulnerabilities')state.vulnerabilities=e.target.value;if(e.target.dataset.playerNumber!==undefined)state.players[e.target.dataset.playerNumber].number=e.target.value;if(e.target.dataset.playerPosition!==undefined)state.players[e.target.dataset.playerPosition].position=e.target.value;if(e.target.dataset.playerName!==undefined)state.players[e.target.dataset.playerName].name=e.target.value;if(e.target.dataset.playerRating!==undefined)state.players[e.target.dataset.playerRating].rating=e.target.value;if(e.target.dataset.playerFoot!==undefined)state.players[e.target.dataset.playerFoot].foot=e.target.value;if(e.target.dataset.playerRole!==undefined)state.players[e.target.dataset.playerRole].role=e.target.value;if(e.target.dataset.playerPositive!==undefined)state.players[e.target.dataset.playerPositive].positive=e.target.value;if(e.target.dataset.playerImprove!==undefined)state.players[e.target.dataset.playerImprove].improve=e.target.value;save()});
$('#eventTypeFilter').innerHTML+=eventTypes.map(e=>`<option value="${e.id}">${e.name}</option>`).join('');
$('#eventTypeFilter').onchange=renderEvents;$('#eventPeriodFilter').onchange=renderEvents;
$('#printBtn').onclick=()=>window.print();
$('#saveReportBtn').onclick=saveCurrentReport;
$('#shareBtn').onclick=async()=>{renderReport();const text=`Relatório: ${state.team}\n${generateInsights().join('\n')}\nAtaques: ${count('attack')} · Remates: ${count('shot')} · Golos: ${state.score}\nPontos fortes: ${state.strengths||'—'}\nPontos fracos: ${state.weaknesses||state.vulnerabilities||'—'}\nComo explorar: ${state.howToExploit||'—'}\nTreino recomendado: ${state.trainingRecommendations||'—'}`;if(navigator.share){try{await navigator.share({title:`Observação — ${state.team}`,text})}catch{}}else{await navigator.clipboard.writeText(text);toast('Relatório copiado')}};
sync();renderReportLibrary(); if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js?v=7');

// Construtor de exercícios
const canvas=$('#tacticsCanvas'),ctx=canvas.getContext('2d');
const boardBlank=()=>({id:null,name:'',category:'',age:'',players:'',space:'',objective:'',duration:'',sets:'',rest:'',equipment:'',description:'',rules:'',variants:'',success:'',pitch:'full',items:[],frames:[]});
let board=boardBlank(),boardTool='select',boardHistory=[],dragIndex=-1,selectedIndex=-1,selectedFrameIndex=-1,drawStart=null,previewPoint=null,animationRunning=false;
let exercises=JSON.parse(localStorage.getItem('rf-football-exercises')||'[]');
const toolNames={select:'Selecione e arraste os elementos',home:'Toque no campo para adicionar Equipa A',away:'Toque no campo para adicionar Equipa B',neutral:'Toque no campo para adicionar um joker',ball:'Toque no campo para adicionar uma bola',cone:'Toque no campo para adicionar um cone',run:'Arraste para desenhar uma corrida',dribble:'Arraste para desenhar uma condução',pass:'Arraste para desenhar um passe',shot:'Arraste para indicar a direção do remate',corner:'Arraste para desenhar o canto',press:'Arraste para indicar a pressão',zone:'Arraste para marcar uma zona',delete:'Toque num elemento para apagar'};
function boardPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}}
function boardSnapshot(){boardHistory.push(JSON.stringify(board.items));if(boardHistory.length>30)boardHistory.shift()}
function drawPitch(){
  const w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#347f4d';ctx.fillRect(0,0,w,h);
  for(let i=0;i<10;i++){ctx.fillStyle=i%2?'rgba(255,255,255,.025)':'rgba(0,0,0,.025)';ctx.fillRect(i*w/10,0,w/10,h)}
  if(board.pitch==='blank')return;ctx.strokeStyle='rgba(255,255,255,.9)';ctx.lineWidth=5;ctx.strokeRect(22,22,w-44,h-44);
  if(board.pitch==='full'){
    ctx.beginPath();ctx.moveTo(w/2,22);ctx.lineTo(w/2,h-22);ctx.stroke();ctx.beginPath();ctx.arc(w/2,h/2,92,0,Math.PI*2);ctx.stroke();
    [[22,1],[w-22,-1]].forEach(([x,d])=>{ctx.strokeRect(d>0?x:x-165,h/2-145,165,290);ctx.strokeRect(d>0?x:x-62,h/2-78,62,156);ctx.beginPath();ctx.arc(x+d*112,h/2,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill()});
  }else{
    ctx.beginPath();ctx.moveTo(22,h/2);ctx.lineTo(w-22,h/2);ctx.stroke();ctx.beginPath();ctx.arc(w/2,22,105,0,Math.PI);ctx.stroke();ctx.strokeRect(w/2-175,h-185,350,163);ctx.strokeRect(w/2-75,h-82,150,60);ctx.beginPath();ctx.arc(w/2,h-132,3,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();
  }
}
function arrowHead(x1,y1,x2,y2,color,dashed,scale=1,curve=0){const dx=x2-x1,dy=y2-y1,len=Math.max(1,Math.hypot(dx,dy)),offset=curve*2.5,cx=(x1+x2)/2-dy/len*offset,cy=(y1+y2)/2+dx/len*offset,a=curve?Math.atan2(y2-cy,x2-cx):Math.atan2(dy,dx),size=18*scale;ctx.save();ctx.strokeStyle=color;ctx.fillStyle=color;ctx.lineWidth=8*scale;ctx.lineCap='round';ctx.setLineDash(dashed?[18*scale,13*scale]:[]);ctx.beginPath();ctx.moveTo(x1,y1);if(curve)ctx.quadraticCurveTo(cx,cy,x2,y2);else ctx.lineTo(x2,y2);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.moveTo(x2,y2);ctx.lineTo(x2-size*Math.cos(a-.55),y2-size*Math.sin(a-.55));ctx.lineTo(x2-size*Math.cos(a+.55),y2-size*Math.sin(a+.55));ctx.closePath();ctx.fill();ctx.restore()}
function drawItem(o){
  const scale=o.scale||1;
  if(['run','dribble','pass','shot','corner','press'].includes(o.type)){const color={run:'#ffe458',dribble:'#53efff',pass:'#fff',shot:'#ff5964',corner:'#ffd447',press:'#d79cff'}[o.type];arrowHead(o.x,o.y,o.x2,o.y2,color,['run','dribble','press'].includes(o.type),scale,o.curve||0);return}
  if(o.type==='zone'){ctx.save();ctx.fillStyle='rgba(255,220,60,.18)';ctx.strokeStyle='#ffe458';ctx.lineWidth=5*scale;ctx.setLineDash([14*scale,10*scale]);ctx.fillRect(o.x,o.y,o.x2-o.x,o.y2-o.y);ctx.strokeRect(o.x,o.y,o.x2-o.x,o.y2-o.y);ctx.restore();return}
  ctx.save();ctx.translate(o.x,o.y);ctx.scale(scale,scale);
  if(['home','away','neutral'].includes(o.type)){const colors={home:'#1677ff',away:'#ef3340',neutral:'#f7d447'};ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.fillStyle=o.color||colors[o.type];ctx.fill();ctx.strokeStyle=o.locked?'#ffd447':'#fff';ctx.lineWidth=5;ctx.stroke();ctx.fillStyle=o.type==='neutral'?'#2d321e':'#fff';ctx.font='bold 22px system-ui';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(o.label,0,1);if(o.name){ctx.font='bold 13px system-ui';const width=ctx.measureText(o.name).width+12;ctx.fillStyle='rgba(6,35,24,.82)';ctx.fillRect(-width/2,32,width,21);ctx.fillStyle='#fff';ctx.fillText(o.name,0,43)}}
  if(o.type==='ball'){ctx.beginPath();ctx.arc(0,0,16,0,Math.PI*2);ctx.fillStyle='#fff';ctx.fill();ctx.strokeStyle='#17241c';ctx.lineWidth=4;ctx.stroke();ctx.fillStyle='#17241c';ctx.font='19px serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('•',0,0)}
  if(o.type==='cone'){ctx.beginPath();ctx.moveTo(0,-22);ctx.lineTo(20,18);ctx.lineTo(-20,18);ctx.closePath();ctx.fillStyle='#ff8b22';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.stroke()}
  ctx.restore();
}
function renderBoard(){drawPitch();board.items.forEach(drawItem);if(selectedIndex>=0&&board.items[selectedIndex]&&!animationRunning){const o=board.items[selectedIndex],s=o.scale||1;ctx.save();ctx.strokeStyle='#fff';ctx.lineWidth=3;ctx.setLineDash([7,6]);if(['run','dribble','pass','shot','corner','press','zone'].includes(o.type)){const pad=12+Math.abs(o.curve||0)*2.5;ctx.strokeRect(Math.min(o.x,o.x2)-pad,Math.min(o.y,o.y2)-pad,Math.abs(o.x2-o.x)+pad*2,Math.abs(o.y2-o.y)+pad*2)}else{ctx.beginPath();ctx.arc(o.x,o.y,35*s,0,Math.PI*2);ctx.stroke()}ctx.restore()}if(drawStart&&previewPoint){drawItem({type:boardTool,x:drawStart.x,y:drawStart.y,x2:previewPoint.x,y2:previewPoint.y,scale:1,curve:0})}}
function itemHit(p){for(let i=board.items.length-1;i>=0;i--){const o=board.items[i],s=o.scale||1;if(['run','dribble','pass','shot','corner','press','zone'].includes(o.type)){const pad=20*s+Math.abs(o.curve||0)*2.5,minX=Math.min(o.x,o.x2)-pad,maxX=Math.max(o.x,o.x2)+pad,minY=Math.min(o.y,o.y2)-pad,maxY=Math.max(o.y,o.y2)+pad;if(p.x>=minX&&p.x<=maxX&&p.y>=minY&&p.y<=maxY)return i}else if(Math.hypot(p.x-o.x,p.y-o.y)<38*s)return i}return-1}
function nextLabel(type){return String(board.items.filter(x=>x.type===type).length+1)}
function newUid(){return Date.now().toString(36)+Math.random().toString(36).slice(2,7)}
function updateSizeControl(){const o=board.items[selectedIndex],range=$('#objectSize');range.disabled=!o;range.value=o?Math.round((o.scale||1)*100):100;$('#objectSizeValue').value=range.value+'%';updateTrajectoryControl();updateObjectProperties()}
function updateTrajectoryControl(){const o=board.items[selectedIndex],enabled=o&&['dribble','pass','shot','corner','press'].includes(o.type),range=$('#trajectoryCurve');range.disabled=!enabled;$('#straightTrajectory').disabled=!enabled;range.value=enabled?(o.curve||0):0;$('#trajectoryCurveValue').value=(Number(range.value)>0?'+':'')+range.value+'°'}
function updateObjectProperties(){const o=board.items[selectedIndex],isPlayer=o&&['home','away','neutral'].includes(o.type),panel=$('#playerProperties');panel.hidden=!isPlayer;if(!isPlayer)return;$('#playerNumber').value=o.label||'';$('#playerName').value=o.name||'';$('#playerColor').value=o.color||({home:'#1677ff',away:'#ef3340',neutral:'#f7d447'}[o.type]);$('#lockObject').textContent=o.locked?'🔒 Desbloquear':'🔓 Bloquear'}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();const p=boardPoint(e),hit=itemHit(p);canvas.setPointerCapture(e.pointerId);
  if(animationRunning)return;
  if(boardTool==='select'){selectedIndex=hit;updateSizeControl();updateObjectProperties();renderBoard();if(hit>=0&&!board.items[hit].locked){boardSnapshot();dragIndex=hit}else if(hit>=0&&board.items[hit].locked)toast('Elemento bloqueado') ;return}
  if(boardTool==='delete'){if(hit>=0){boardSnapshot();board.items.splice(hit,1);selectedIndex=-1;updateSizeControl();updateObjectProperties();renderBoard()}return}
  if(['run','dribble','pass','shot','corner','press','zone'].includes(boardTool)){boardSnapshot();drawStart=p;previewPoint=p;return}
  if(['home','away','neutral','ball','cone'].includes(boardTool)){boardSnapshot();const colors={home:'#1677ff',away:'#ef3340',neutral:'#f7d447'};board.items.push({uid:newUid(),type:boardTool,x:p.x,y:p.y,label:nextLabel(boardTool),scale:1,color:colors[boardTool]});selectedIndex=board.items.length-1;updateSizeControl();updateObjectProperties();renderBoard()}
});
canvas.addEventListener('pointermove',e=>{const p=boardPoint(e);if(dragIndex>=0){const o=board.items[dragIndex],dx=p.x-o.x,dy=p.y-o.y;o.x=p.x;o.y=p.y;if(o.x2!==undefined){o.x2+=dx;o.y2+=dy}renderBoard()}else if(drawStart){previewPoint=p;renderBoard()}});
canvas.addEventListener('pointerup',()=>{if(drawStart&&previewPoint&&Math.hypot(previewPoint.x-drawStart.x,previewPoint.y-drawStart.y)>15){board.items.push({uid:newUid(),type:boardTool,x:drawStart.x,y:drawStart.y,x2:previewPoint.x,y2:previewPoint.y,scale:1,curve:0});selectedIndex=board.items.length-1;updateSizeControl();updateObjectProperties()}dragIndex=-1;drawStart=null;previewPoint=null;renderBoard()});
const boardFields={exerciseName:'name',exerciseCategory:'category',exerciseAge:'age',exercisePlayers:'players',exerciseSpace:'space',exerciseObjective:'objective',exerciseDuration:'duration',exerciseSets:'sets',exerciseRest:'rest',exerciseEquipment:'equipment',exerciseDescription:'description',exerciseRules:'rules',exerciseVariants:'variants',exerciseSuccess:'success'};
function syncBoardForm(){Object.entries(boardFields).forEach(([id,key])=>board[key]=$('#'+id).value);board.pitch=$('#pitchType').value}
function fillBoardForm(){board.items=board.items||[];board.frames=(board.frames||[]).map((f,i)=>Array.isArray(f)?{id:newUid(),name:`Etapa ${i+1}`,duration:900,items:f}:f);board.items.forEach(o=>{o.uid=o.uid||newUid();o.scale=o.scale||1;o.curve=o.curve||0});Object.entries(boardFields).forEach(([id,key])=>$('#'+id).value=board[key]||'');$('#pitchType').value=board.pitch;selectedIndex=-1;selectedFrameIndex=-1;updateSizeControl();renderTimeline();renderBoard() }
function escapeText(s){return String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function renderExerciseList(){
  $('#exerciseCount').textContent=`${exercises.length} guardados`;const list=$('#exerciseList');list.className=exercises.length?'':'';
  list.innerHTML=exercises.length?exercises.map(x=>`<div class="exercise-row"><div><h3>${escapeText(x.name||'Exercício sem nome')}</h3><p>${escapeText(x.category||'Sem categoria')} · ${escapeText(x.objective||'Sem objetivo')} · ${escapeText(x.duration||'Duração não definida')}</p></div><div class="exercise-row-actions"><button data-load-exercise="${x.id}">Abrir</button><button class="delete-exercise" data-delete-exercise="${x.id}">×</button></div></div>`).join(''):'Ainda não existem exercícios guardados.';
}
function newBoard(){board=boardBlank();boardHistory=[];selectedIndex=-1;fillBoardForm();toast('Novo exercício')}
$$('[data-module]').forEach(b=>b.onclick=()=>{$$('[data-module]').forEach(x=>x.classList.toggle('active',x===b));$('#observationModule').classList.toggle('active',b.dataset.module==='observation');$('#builderModule').classList.toggle('active',b.dataset.module==='builder');$('#appTitle').textContent=b.dataset.module==='builder'?'Construtor de Exercícios':state.scope==='own'?'Análise da Minha Equipa':'Observação do Adversário';$('#resetBtn').style.visibility=b.dataset.module==='builder'?'hidden':'visible';if(b.dataset.module==='builder')renderBoard()});
$('#toolbox').onclick=e=>{const b=e.target.closest('[data-tool]');if(!b)return;boardTool=b.dataset.tool;$$('#toolbox button').forEach(x=>x.classList.toggle('active',x===b));$('#builderStatus').textContent=toolNames[boardTool]};
$('#pitchType').onchange=e=>{board.pitch=e.target.value;renderBoard()};
Object.keys(boardFields).forEach(id=>$('#'+id).addEventListener('input',syncBoardForm));
$('#undoBoard').onclick=()=>{if(boardHistory.length){board.items=JSON.parse(boardHistory.pop());selectedIndex=-1;updateSizeControl();renderBoard()}};
$('#clearBoard').onclick=()=>{if(board.items.length&&confirm('Limpar todos os elementos do campo?')){boardSnapshot();board.items=[];selectedIndex=-1;updateSizeControl();renderBoard()}};
$('#newExercise').onclick=()=>{if(!board.items.length&&!board.name)newBoard();else if(confirm('Criar um exercício novo?'))newBoard()};
$('#saveExercise').onclick=()=>{syncBoardForm();if(!board.name.trim()){toast('Indique o nome do exercício');$('#exerciseName').focus();return}if(!board.id)board.id=Date.now();const i=exercises.findIndex(x=>x.id===board.id),copy=JSON.parse(JSON.stringify(board));if(i>=0)exercises[i]=copy;else exercises.unshift(copy);const updatedAt=Date.now();localStorage.setItem('rf-football-exercises',JSON.stringify(exercises));localStorage.setItem('rf-football-exercises-updated',String(updatedAt));window.dispatchEvent(new CustomEvent('rf:exercises-changed',{detail:{data:exercises,updatedAt}}));renderExerciseList();toast('Exercício guardado')};
$('#exerciseList').onclick=e=>{const load=e.target.dataset.loadExercise,del=e.target.dataset.deleteExercise;if(load){const found=exercises.find(x=>x.id==load);if(found){board=JSON.parse(JSON.stringify(found));boardHistory=[];fillBoardForm();scrollTo({top:0,behavior:'smooth'});toast('Exercício aberto')}}if(del&&confirm('Apagar este exercício?')){exercises=exercises.filter(x=>x.id!=del);const updatedAt=Date.now();localStorage.setItem('rf-football-exercises',JSON.stringify(exercises));localStorage.setItem('rf-football-exercises-updated',String(updatedAt));window.dispatchEvent(new CustomEvent('rf:exercises-changed',{detail:{data:exercises,updatedAt}}));renderExerciseList()}};
$('#exportExercise').onclick=()=>{syncBoardForm();const out=document.createElement('canvas');out.width=1050;out.height=980;const c=out.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,out.width,out.height);c.fillStyle='#0b3f2e';c.font='bold 36px system-ui';c.fillText(board.name||'Exercício RF Football',28,48);c.fillStyle='#65736c';c.font='18px system-ui';c.fillText([board.category,board.age,board.players&&`${board.players} jogadores`,board.duration].filter(Boolean).join(' · '),28,82);c.fillStyle='#0b3f2e';c.font='bold 18px system-ui';c.fillText(board.objective||'Objetivo não definido',28,116);c.fillStyle='#65736c';c.font='16px system-ui';c.fillText([board.space&&`Espaço: ${board.space}`,board.sets,board.rest&&`Rec.: ${board.rest}`].filter(Boolean).join(' · '),28,145);c.drawImage(canvas,0,170,1050,680);c.fillStyle='#0b3f2e';c.font='bold 16px system-ui';c.fillText('Organização',28,885);c.fillStyle='#65736c';c.font='15px system-ui';c.fillText((board.description||'Sem descrição').slice(0,125),28,912);c.fillStyle='#0b3f2e';c.font='bold 16px system-ui';c.fillText('Material',28,944);c.fillStyle='#65736c';c.font='15px system-ui';c.fillText((board.equipment||'Não definido').slice(0,125),115,944);const a=document.createElement('a');a.download=(board.name||'exercicio-rf-football').replace(/[^a-z0-9áàâãéêíóôõúç_-]+/gi,'-')+'.png';a.href=out.toDataURL('image/png');a.click();toast('Ficha exportada')};
$('#objectSize').addEventListener('pointerdown',()=>{if(selectedIndex>=0)boardSnapshot()});
$('#objectSize').addEventListener('input',e=>{const o=board.items[selectedIndex];if(!o)return;o.scale=Number(e.target.value)/100;$('#objectSizeValue').value=e.target.value+'%';renderBoard()});
$('#trajectoryCurve').addEventListener('pointerdown',()=>{if(selectedIndex>=0)boardSnapshot()});
$('#trajectoryCurve').addEventListener('input',e=>{const o=board.items[selectedIndex];if(!o)return;o.curve=Number(e.target.value);$('#trajectoryCurveValue').value=(o.curve>0?'+':'')+o.curve+'°';renderBoard()});
$('#straightTrajectory').onclick=()=>{const o=board.items[selectedIndex];if(!o)return;boardSnapshot();o.curve=0;updateTrajectoryControl();renderBoard()};
['playerNumber','playerName','playerColor'].forEach(id=>$('#'+id).addEventListener('input',()=>{const o=board.items[selectedIndex];if(!o)return;if(id==='playerNumber')o.label=$('#'+id).value;if(id==='playerName')o.name=$('#'+id).value;if(id==='playerColor')o.color=$('#'+id).value;renderBoard()}));
$('#duplicateObject').onclick=()=>{const o=board.items[selectedIndex];if(!o)return;boardSnapshot();const copy={...o,uid:newUid(),x:o.x+45,y:o.y+45};if(copy.x2!==undefined){copy.x2+=45;copy.y2+=45}board.items.push(copy);selectedIndex=board.items.length-1;updateSizeControl();renderBoard();toast('Elemento duplicado')};
$('#lockObject').onclick=()=>{const o=board.items[selectedIndex];if(!o)return;o.locked=!o.locked;updateObjectProperties();renderBoard()};
function updateFrameCount(){const n=(board.frames||[]).length;$('#frameCount').textContent=`${n} ${n===1?'etapa':'etapas'}`;$('#updateFrame').disabled=selectedFrameIndex<0}
function renderTimeline(){updateFrameCount();const timeline=$('#timeline');timeline.innerHTML=board.frames.length?board.frames.map((f,i)=>`<article class="frame-card ${i===selectedFrameIndex?'active':''}" data-frame-card="${i}"><div class="frame-card-top"><input data-frame-name="${i}" value="${escapeText(f.name||`Etapa ${i+1}`)}" aria-label="Nome da etapa"></div><small>${f.items.length} elementos · ${Math.round((f.duration||900)/100)/10}s</small><div class="frame-actions"><button title="Ver etapa" data-frame-view="${i}">◉</button><button title="Mover para trás" data-frame-left="${i}">←</button><button title="Mover para a frente" data-frame-right="${i}">→</button><button title="Duplicar" data-frame-copy="${i}">⧉</button><button class="danger" title="Eliminar" data-frame-delete="${i}">×</button></div></article>`).join(''):'<div class="empty">Guarde a primeira etapa para criar a animação.</div>'}
$('#addFrame').onclick=()=>{if(!board.items.length){toast('Adicione jogadores ao campo primeiro');return}board.frames=board.frames||[];board.frames.push({id:newUid(),name:`Etapa ${board.frames.length+1}`,duration:Number($('#animationSpeed').value),items:JSON.parse(JSON.stringify(board.items))});selectedFrameIndex=board.frames.length-1;renderTimeline();toast(`Etapa ${board.frames.length} guardada`)};
$('#updateFrame').onclick=()=>{if(selectedFrameIndex<0)return;board.frames[selectedFrameIndex].items=JSON.parse(JSON.stringify(board.items));board.frames[selectedFrameIndex].duration=Number($('#animationSpeed').value);renderTimeline();toast('Etapa atualizada')};
$('#timeline').addEventListener('input',e=>{if(e.target.dataset.frameName!==undefined){board.frames[Number(e.target.dataset.frameName)].name=e.target.value}});
$('#timeline').addEventListener('click',e=>{const get=k=>e.target.dataset[k]!==undefined?Number(e.target.dataset[k]):-1;let i=get('frameView');if(i>=0){selectedFrameIndex=i;board.items=JSON.parse(JSON.stringify(board.frames[i].items));selectedIndex=-1;updateSizeControl();renderTimeline();renderBoard();return}i=get('frameLeft');if(i>0){[board.frames[i-1],board.frames[i]]=[board.frames[i],board.frames[i-1]];selectedFrameIndex=i-1;renderTimeline();return}i=get('frameRight');if(i>=0&&i<board.frames.length-1){[board.frames[i+1],board.frames[i]]=[board.frames[i],board.frames[i+1]];selectedFrameIndex=i+1;renderTimeline();return}i=get('frameCopy');if(i>=0){const copy=JSON.parse(JSON.stringify(board.frames[i]));copy.id=newUid();copy.name+=' (cópia)';board.frames.splice(i+1,0,copy);selectedFrameIndex=i+1;renderTimeline();return}i=get('frameDelete');if(i>=0&&confirm('Eliminar esta etapa?')){board.frames.splice(i,1);selectedFrameIndex=-1;renderTimeline()}});
function interpolateItems(from,to,t){
  const byId=new Map(to.map(o=>[o.uid,o]));const ease=t<.5?2*t*t:1-Math.pow(-2*t+2,2)/2;
  const result=from.map(a=>{const b=byId.get(a.uid)||a,c={...a};['x','y','x2','y2','scale','curve'].forEach(k=>{if(Number.isFinite(a[k])&&Number.isFinite(b[k]))c[k]=a[k]+(b[k]-a[k])*ease});return c});
  to.forEach(b=>{if(!result.some(a=>a.uid===b.uid)&&t>.45)result.push({...b})});return result;
}
function animateLeg(from,to,duration){return new Promise(resolve=>{const started=performance.now();function tick(now){const t=Math.min(1,(now-started)/duration);board.items=interpolateItems(from,to,t);renderBoard();if(t<1)requestAnimationFrame(tick);else resolve()}requestAnimationFrame(tick)})}
$('#playAnimation').onclick=async()=>{if(animationRunning)return;board.frames=board.frames||[];if(board.frames.length<2){toast('Guarde pelo menos duas etapas');return}animationRunning=true;selectedIndex=-1;selectedFrameIndex=-1;updateSizeControl();renderTimeline();$('#playAnimation').textContent='❚❚ A animar…';for(let i=0;i<board.frames.length-1;i++)await animateLeg(board.frames[i].items,board.frames[i+1].items,board.frames[i+1].duration||Number($('#animationSpeed').value));board.items=JSON.parse(JSON.stringify(board.frames.at(-1).items));animationRunning=false;$('#playAnimation').textContent='▶ Animar';renderBoard();toast('Animação concluída')};
fillBoardForm();renderExerciseList();
